#define MIN_VALUE  0.0001
#define IMAGE_SPLIT 9.0

float SphereSDF(vec3 center, float r, vec3 p)
{
    return length(p - center) - r;
}
float sdBox( vec3 center, vec3 b, vec3 p)
{
  vec3 q = abs(p - center) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float Scene(vec3 p)
{
    float dist = 10000.0;
    dist = min(dist, SphereSDF(vec3(-3.0, 0.0, -16.5), 0.5, p));
    dist = min(dist, SphereSDF(vec3(-0.0 + sin(iTime*3.0), 1.5-cos(iTime*3.0), -10.0 + cos(iTime*3.0)), 0.3, p));

    float tmp = sdBox(vec3(2.0, 3.0, -12.5), vec3(1.0, 1.0, 1.0), p);
    //tmp = max(tmp, -SphereSDF(vec3(2.0 + sin(iTime), 0.0, -15.5), 1.2, p));
    float tmp2 = sdBox(vec3(0.0, 3.0, -12.5), vec3(2.0, .5, .5), p);
    tmp2 = min(tmp2, SphereSDF(vec3(2.0, 3.0, -12.5), 1.0, p));

    float rate = sin(iTime)*0.5 + 0.5;
    tmp2 = tmp2 * rate + tmp * (1.0-rate);
    dist = min(dist, tmp2);

    float plat = max(p.y+1.0, 14.0+p.z);
    dist = min(dist, plat);
    dist = min(dist, p.z + 20.0);

    dist = min(dist, sdBox(vec3(-4.0, 1.0, -12.5), vec3(1.0, 1.0, 1.0), p));
    dist = max(dist, -SphereSDF(vec3(-4.0, 1.0, -12.5), 1.2, p));
    dist = min(dist, SphereSDF(vec3(-4.0, .5, -12.5), 0.5, p));

    return dist;
}

vec3 GetRay(vec3 cameraPos, vec3 cameraLookAt, float fov, vec2 fragCoord, vec2 fullResolution)
{
    float dist = 1.0;
    float harfHeight = tan(fov/2.0);
    float harfWidth = harfHeight / fullResolution.y * fullResolution.x;

    vec3 camForward = normalize(cameraLookAt - cameraPos);
    vec3 camRight = normalize(cross(vec3(0.0, 1.0, 0.0), camForward));
    vec3 camUp = normalize(cross(camForward, camRight));

    return normalize(camForward 
        + camUp * harfHeight * (fragCoord.y / fullResolution.y - 0.5) * 2.0
        + camRight * harfWidth * (fragCoord.x / fullResolution.x - 0.5) * 2.0
        );    
}

vec3 RayPos(vec3 startPos, vec3 ray, float maxDist)
{
    float totalDist = 0.0;
    float dist = Scene(startPos);
    int count = 0;
    while (dist > MIN_VALUE && totalDist < maxDist && count < 300){
        count ++;
        startPos = startPos + ray * dist;
        totalDist += dist;
        dist = Scene(startPos);
    }
    totalDist = min(maxDist, totalDist);
    return startPos + ray * totalDist;
}

vec2 calcUV(vec2 uv, vec2 totalSize)
{
    int posX, posY;
    int scale = 3;
    posX = int(uv.x * totalSize.x / float(scale)) * scale;
    posY = int(uv.y * totalSize.y / float(scale)) * scale;
    return vec2(float(posX), float(posY)) / totalSize;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float mouseY = (iMouse.y) / iResolution.y * 10.0 - 2.0;
    float eyeAngleLeft = iMouse.x / iResolution.x * 3.0 + 5.0;
    eyeAngleLeft = max(min(eyeAngleLeft, 7.0), 2.5);
    float eyeAngleRight = eyeAngleLeft + 0.5;
    float eyeDist = 15.0;
    float mouseXCtrlLeft = sin(eyeAngleLeft) * eyeDist;
    float mouseZCtrlLeft =  cos(eyeAngleLeft) * eyeDist;
    float mouseXCtrlRight = sin(eyeAngleRight) * eyeDist;
    float mouseZCtrlRight = cos(eyeAngleRight) * eyeDist;
    vec3 cameraPosLeft = vec3(mouseXCtrlLeft, mouseY, - 15.0 + mouseZCtrlLeft);
    vec3 cameraPosRight = vec3(mouseXCtrlRight, mouseY, - 15.0 + mouseZCtrlRight);
    vec3 cameraCenter = (cameraPosLeft + cameraPosRight) / 2.0;
    float nearFace = 5.0;
    float farFace = 100.0;
    vec3 cameraLookAt = vec3(0.0, -5.0, -15.5);


            // vec3 leftRay = GetRay(cameraPosLeft, cameraLookAt, 60.0 / 180.0 * 3.14159, fragCoord, iResolution.xy);
            // vec3 targetPos = RayPos(cameraPosLeft, leftRay, 100.0);
            // fragColor = vec4(vec3(length(targetPos-cameraPosLeft))/100.0, 1.0);
            // return;

    vec2 uv = fragCoord.xy / iResolution.xy;
    if (uv.x > 10.0)
    {
        fragColor = texture(iChannel0, calcUV(uv, iResolution.xy));
    }
    else
    {
        vec2 coord = fragCoord;
        int count = 0;
        while (coord.x < iResolution.x - iResolution.x / IMAGE_SPLIT && count < 10)
        {
            count ++;
            vec3 leftRay = GetRay(cameraPosLeft, cameraLookAt, 60.0 / 180.0 * 3.14159, coord, iResolution.xy);
            vec3 targetPos = RayPos(cameraPosLeft, leftRay, 200.0);
            vec3 rightRay = normalize(targetPos - cameraPosRight);
            vec3 rightRayPos = RayPos(cameraPosRight, rightRay, length(targetPos - cameraPosRight));

            float cosLeft = dot(leftRay, normalize(cameraLookAt - cameraCenter));
            float cosRight = dot(rightRay, normalize(cameraLookAt - cameraCenter));
            float viewDist = length(leftRay/cosLeft-rightRay/cosLeft);
            vec2 uvN = coord / iResolution.xy +vec2(1.0/IMAGE_SPLIT - viewDist / IMAGE_SPLIT, 0.0);

            coord = uvN * iResolution.xy;
        }
        fragColor = texture(iChannel0, calcUV(coord / iResolution.xy, iResolution.xy));
    }
    vec2 pointPos = vec2(iResolution.x * 0.5, iResolution.y * 0.9);
    float pointDist = iResolution.x * 0.05;
    float pointSize = iResolution.x * 0.01;
    if (length(vec2(pointPos.x-pointDist*0.5,pointPos.y) - fragCoord) < pointSize ||
        length(vec2(pointPos.x+pointDist*0.5,pointPos.y) - fragCoord) < pointSize
        )
    {
        fragColor = vec4(0.8, 0.3, 0.3, 1.0);
    }
}

float random (vec2 st)
{
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord/iResolution.xy;
    float light = random(fragCoord / 100.0 *fract(sin(iTime)+0.1));
    float light2 = random(fragCoord / 107.0 *fract(sin(iTime)+0.2));
    float light3 = random(fragCoord / 1013.0 *fract(sin(iTime)+0.3));
    fragColor = vec4(light, light2, light3, 1.0);
    // fragColor = vec4(vec3(random(fragCoord / 100.0)), 1.0);
}
